1	// Runs the suite through `claude plugin eval` and leaves the result in evals/cases/results.
2	// Usage: run.mjs [--bare] [--case <glob>] [--tag <tag>] [--runs <n>] [--model <m>] [--effort <level>]
3	//                [--max-cost-usd <usd>] [--dry-run]
4	// --bare runs evals/bare/ against an empty plugin: the same requests with nothing of AMBICODE loaded.
5	import { spawnSync } from 'node:child_process';
6	import { cpSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
7	import { harvest } from './context.mjs';
8	import { CASES, caseOf } from './cases.mjs';
9	import { metricsOf } from './metrics.mjs';
10	import { NAVIGATOR_TAG, isNavigatorCase, navigatorMetrics, navigatorTruth } from './navigator-cases.mjs';
11	import { fileURLToPath } from 'node:url';
12	import path from 'node:path';
13	
14	export const DEFAULTS = { model: 'claude-sonnet-5-5', effort: 'low', runs: '1', maxCostUsd: '15', concurrency: '4' };
15	const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
16	export const RESULTS = path.join(REPO, 'evals', 'cases', 'results');
17	// Outside the plugin, because the harness walks the whole target directory; .tmp/ is gitignored.
18	export const NAKED = path.join(REPO, '.tmp', 'naked');
19	
20	function option(argv, name) {
21	  const at = argv.indexOf(name);
22	  return at >= 0 ? (argv[at + 1] ?? null) : null;
23	}
24	
25	/** The harness argv and environment of one run; everything is fixed here so the run can be reproduced. */
26	export function plan(argv, defaults = DEFAULTS, results = RESULTS) {
27	  const arm = argv.includes('--bare') ? 'bare' : 'plugin';
28	  const model = option(argv, '--model') ?? defaults.model;
29	  const effort = option(argv, '--effort') ?? defaults.effort;
30	  const result = path.join(results, `${arm}.json`);
31	  const out = [
32	    'plugin', 'eval', arm === 'bare' ? NAKED : REPO,
33	    '--eval-dir', arm === 'bare' ? 'evals/bare' : 'evals/cases',
34	    '--scaffold', '--trust-plugin', '--no-publish',
35	    // Kept so the context size can be read from each trace; harvest() deletes every sandbox afterwards.
36	    '--keep-temp',
37	    // One arm per run: a plugin case's prompt types /ambicode:<skill>, which means nothing with no plugin loaded.
38	    '--ablation', 'none',
39	    // The plugin navigator arm only relays the navigator, which reads with Read and Grep: no shell for the session.
40	    ...(arm === 'plugin' && option(argv, '--tag') === NAVIGATOR_TAG ? [] : ['--allow-tools', 'Bash', 'Edit', 'Write']),
41	    '--model', model,
42	    '--runs', option(argv, '--runs') ?? defaults.runs,
43	    '-j', defaults.concurrency,
44	    '--max-cost-usd', option(argv, '--max-cost-usd') ?? defaults.maxCostUsd,
45	    '--json', result,
46	  ];
47	  for (const name of ['--case', '--tag']) {
48	    const value = option(argv, name);
49	    if (value !== null) out.push(name, value);
50	  }
51	  // The harness has no exclude option: an unfiltered run lists the skill tags, which the navigator cases do not carry.
52	  if (option(argv, '--case') === null && option(argv, '--tag') === null) {
53	    for (const tag of new Set(CASES.flatMap((one) => one.tags))) out.push('--tag', tag);
54	  }
55	  // The harness has no effort flag; the variable reaches the run's claude child (probed 2026-10-12: `env=[low]`).
56	  const env = { CLAUDE_CODE_EFFORT_LEVEL: effort };
57	  return { arm, argv: out, env, result };
58	}
59	
60	/** An empty plugin holding a copy of evals/bare, with each scaffold pointed back at this repository's fixtures. */
61	export function buildNaked(repo = REPO, naked = NAKED) {
62	  rmSync(naked, { recursive: true, force: true });
63	  mkdirSync(path.join(naked, '.claude-plugin'), { recursive: true });
64	  writeFileSync(path.join(naked, '.claude-plugin', 'plugin.json'), `${JSON.stringify({ name: 'naked', version: '0.0.0', description: 'No components: the bare arm.' })}\n`);
65	  const target = path.join(naked, 'evals', 'bare');
66	  cpSync(path.join(repo, 'evals', 'bare'), target, { recursive: true });
67	  for (const name of readdirSync(target)) {
68	    const file = path.join(target, name, 'scaffold.sh');
69	    try {
70	      writeFileSync(file, readFileSync(file, 'utf8').replaceAll('$(cd "$(dirname "$0")/../../.." && pwd)', repo), { mode: 0o755 });
71	    } catch (error) {
72	      if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') throw error;
73	    }
74	  }
75	}
76	
77	// Either variable overrides every subagent's model, so an inherited one hides the agent's own `model:` (seen 2026-10-20: haiku navigator ran on sonnet).
78	export function childEnv(base, env) {
79	  const out = { ...base, ...env };
80	  delete out.CLAUDE_CODE_SUBAGENT_MODEL;
81	  delete out.CLAUDE_CODE_SUBAGENT_MODEL_FORCE;
82	  return out;
83	}
84	
85	const REAL = {
86	  spawn: (cmd, args, env) => spawnSync(cmd, args, { stdio: 'inherit', env: childEnv(process.env, env) }).status,
87	  harvest,
88	  truthOf: navigatorTruth,
89	  tracesRoot: path.join(RESULTS, 'traces'),
90	};
91	
92	/** Recall of a navigator run as the recall-NN graders scored it: passed / total; undefined when the case has none. */
93	export function recallOfGraders(graders) {
94	  const recalls = (graders ?? []).filter((grader) => /^recall-\d+-/.test(grader.name));
95	  return recalls.length === 0 ? undefined : Number((recalls.filter((grader) => grader.passed).length / recalls.length).toFixed(3));
96	}
97	
98	/**
99	 * Navigator metrics: precision, F1 and the folder lists from scoreNavigator, recall pinned to the graders. A computed recall that
100	 * differs is a bug in one of the two, so the grader value is written and `mismatch` is set instead of hiding it.
101	 */
102	export function navigatorRunMetrics(truth, traceText, graders) {
103	  const graded = recallOfGraders(graders);
104	  if (truth === null || traceText === undefined) return graded === undefined ? {} : { recall: graded };
105	  const metrics = navigatorMetrics(truth, traceText);
106	  if (graded !== undefined && graded !== metrics.recall) return { ...metrics, recall: graded, mismatch: true };
107	  return metrics;
108	}
109	
110	/** One `claude plugin eval` call: harvest, metrics; leaves run.result holding this call's result. */
111	export function runCase(run, deps = REAL) {
112	  const status = deps.spawn('claude', run.argv, run.env);
113	  // Exit 1 is a case below the harness threshold (1.0) and 2 a partial result (cost ceiling): both are results
114	  // (`partial` is the harness's own flag in the JSON). Anything else is a harness failure with no result.
115	  if (![0, 1, 2].includes(status)) return { status: status ?? 1, result: null };
116	  const result = JSON.parse(readFileSync(run.result, 'utf8'));
117	  const stamp = String(result.startedAt ?? Date.now()).replace(/[:.]/g, '-');
118	  // Per suite run: clearing one shared folder lost the traces of every earlier run (2026-10-12).
119	  deps.harvest(result, path.join(deps.tracesRoot, run.arm, stamp));
120	  for (const evalCase of result.cases ?? []) {
121	    const navigator = isNavigatorCase(evalCase.name);
122	    const spec = navigator ? undefined : caseOf(evalCase.name)?.metrics;
123	    if (!navigator && spec === undefined) continue;
124	    for (const runs of Object.values(evalCase.arms ?? {})) for (const one of runs ?? []) {
125	      if (navigator) one.metrics = navigatorRunMetrics(deps.truthOf?.(evalCase.name) ?? null, one.trace ? readFileSync(one.trace, 'utf8') : undefined, one.graders);
126	      else if (one.trace) one.metrics = metricsOf(spec, readFileSync(one.trace, 'utf8'));
127	    }
128	  }
129	  writeFileSync(run.result, `${JSON.stringify(result, null, 2)}\n`);
130	  // The viewer reads one copy per run (<results>/<stamp>/); the harness's own copy there lacks our fields, so the viewer
