use crate::safety::{check_setpoint_dc, SafetyError};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Segment {
    pub minutes: u32,
    pub target_dc: i32,
}

#[derive(Debug, Clone)]
pub struct Schedule {
    segments: Vec<Segment>,
}

impl Schedule {
    pub fn new(segments: Vec<Segment>) -> Result<Self, SafetyError> {
        if segments.is_empty() {
            return Err(SafetyError::Empty);
        }
        for segment in &segments {
            check_setpoint_dc(segment.target_dc)?;
        }
        Ok(Self { segments })
    }

    pub fn total_minutes(&self) -> u32 {
        self.segments.iter().map(|segment| segment.minutes).sum()
    }

    pub fn target_at_dc(&self, minute: u32) -> i32 {
        let mut elapsed = 0;
        for segment in &self.segments {
            elapsed += segment.minutes;
            if minute < elapsed {
                return segment.target_dc;
            }
        }
        self.segments
            .last()
            .map(|segment| segment.target_dc)
            .expect("invariant: Schedule::new rejects an empty segment list")
    }
}
