import type { Express } from 'express';
import { SetpointError, startFiring } from './lib/engineClient.js';
import { findFiring, saveFiring } from './lib/store.js';

export function register(app: Express): void {
  app.post('/firings', async (req, res) => {
    const id = `f-${Date.now()}`;
    try {
      await startFiring(id, req.body.segments);
    } catch (error) {
      if (error instanceof SetpointError) return res.status(422).json({ error: error.message });
      throw error;
    }
    saveFiring({ id, segments: req.body.segments, startedAt: new Date().toISOString() });
    return res.status(201).json({ id });
  });

  app.get('/firings/:id', (req, res) => {
    const firing = findFiring(req.params.id);
    return firing === undefined ? res.status(404).end() : res.json(firing);
  });
}
