      checks: { test: { all: 'npx jest', file: 'npx jest --findRelatedTests {file}' }, lint: { all: 'npx eslint .', file: 'npx eslint {file}' } },
      checkPatterns: { test: 'jest', lint: 'eslint' },
      filePatterns: ['jest', 'eslint'],
    }],
    wrongPacks: ['angular-', 'express-', 'python-quality'],
    conventions: [],
