      { id: 'test-names', basis: 'written', quote: 'Name each test `test_<module>__<behaviour>`', location: 'CONTRIBUTING.md:9', draft: String.raw`test_[<\w]+>?__|double[- ]underscore` },
      { id: 'keyword-only-args', basis: 'inferred', quote: 'def tide_window(gauge_id: str, *, start: datetime, hours: int) -> dict:', location: 'src/tidewatch/api.py:16', draft: String.raw`[Kk]eyword[- ]only|, \*, ` },
