import fs from 'fs';
const [,, file] = process.argv;
export function analyze(msgs, opts={}) {
  // msgs: array of parsed lines; scout messages = those with parent_tool_use_id (fixture) 
  const seen = new Map();
  for (const m of msgs) {
    if (m.type!=='assistant') continue;
    const id = m.message.id;
    const e = seen.get(id) || {id, usage:null, content:[], ts:m.timestamp};
    e.usage = m.message.usage; // same input fields across chunks
    for (const c of m.message.content) e.content.push(c);
    e.tsEnd = m.timestamp;
    seen.set(id, e);
  }
  return [...seen.values()];
}
export function kind(c){
  if (c.type!=='tool_use') return null;
  const n=c.name, i=c.input||{};
  if (n==='Bash'){ const s=i.command||'';
    if (/context write/.test(s)) return 'bash:write';
    if (/context tree.*--index/.test(s)) return 'bash:tree-index';
    if (/context tree.*--level/.test(s)) return 'bash:tree-level';
    if (/context tree/.test(s)) return 'bash:tree';
    if (/git ls-files/.test(s)) return 'bash:ls-files';
    return 'bash:other'; }
  return n;
}
if (file) {
  const msgs = fs.readFileSync(file,'utf8').trim().split('\n').map(JSON.parse);
  const sc = msgs.filter(m=>m.parent_tool_use_id);
  const turns = analyze(sc);
  const k={}; let inp=0,cr=0,cw=0, chars=0;
  for (const t of turns){ inp+=t.usage.input_tokens; cr+=t.usage.cache_read_input_tokens; cw+=t.usage.cache_creation_input_tokens;
    for (const c of t.content){ const kk=kind(c); if(kk) {k[kk]=(k[kk]||0)+1; chars+=JSON.stringify(c.input).length;} else if(c.type==='text') chars+=c.text.length; } }
  console.log(JSON.stringify({turns:turns.length,k,inp,cr,cw,chars}));
}
EOF
