import fs from 'fs';
export const P={in:2,out:10,read:0.2,write:2.5}; // $/M, fitted on 15 fixture runs (max err 1.4%)
export const read=f=>fs.readFileSync(f,'utf8').trim().split('\n').map(l=>JSON.parse(l));
export function turnsOf(msgs){
  const seen=new Map();
  for(const m of msgs){ if(m.type!=='assistant'||!m.message?.usage) continue;
    const id=m.message.id; const e=seen.get(id)||{id,content:[],ts:m.timestamp,model:m.message.model};
    e.u=m.message.usage; e.tsEnd=m.timestamp; for(const c of m.message.content) e.content.push(c); seen.set(id,e);}
  return [...seen.values()];
}
export function kind(c){
  if(c.type!=='tool_use') return null; const n=c.name,i=c.input||{};
  if(n==='Bash'){const s=i.command||'';
    if(/context write/.test(s)) return 'Bash:ctx-write';
    if(/context tree.*--index/.test(s)) return 'Bash:tree--index';
    if(/context tree.*--level/.test(s)) return 'Bash:tree--level';
    if(/context tree/.test(s)) return 'Bash:tree';
    return 'Bash:other';}
  return n;
}
export const cch=c=>c.type==='tool_use'?String(c.input?.command??JSON.stringify(c.input)).length:c.type==='text'?c.text.length:c.type==='thinking'?(c.thinking||'').length:0;
export function metrics(msgs){
  const T=turnsOf(msgs); const k={}; let inp=0,cr=0,cw=0,chars=0,thinkChars=0;
  const per=[];
  T.forEach(t=>{inp+=t.u.input_tokens;cr+=t.u.cache_read_input_tokens;cw+=t.u.cache_creation_input_tokens;
    const ks=t.content.map(kind).filter(Boolean); ks.forEach(x=>k[x]=(k[x]||0)+1);
    const ch=t.content.reduce((a,c)=>a+cch(c),0); chars+=ch;
    per.push({ctx:t.u.input_tokens+t.u.cache_read_input_tokens+t.u.cache_creation_input_tokens,cw:t.u.cache_creation_input_tokens,cr:t.u.cache_read_input_tokens,ks,ch});});
  const wall=T.length?(new Date(T.at(-1).tsEnd)-new Date(T[0].ts))/1000:0;
  return {turns:T.length,k,inp,cr,cw,chars,wall,per,model:T[0]?.model};
}
EOF
