export function attribute(sc,tokPerChar=0.52){
  const per=sc.per, n=per.length; const A={}; const add=(k,v)=>A[k]=(A[k]||0)+v;
  const keyOf=(ks)=>ks.length?[...new Set(ks)].sort().join('+'):'final-text';
  // delta tokens by turn i (added after turn i-1's output): attribute to kinds of turn i-1
  const delta=per.map((p,i)=>i===0?p.ctx:p.ctx-per[i-1].ctx);
  const P0=per[0].ctx;
  for(let j=0;j<n;j++){
    // read portion: prefix P0 (turn>0) + deltas of 1..j-1 ... cr_j approx ctx_j - cw_j
    const cr=per[j].cr, cw=per[j].cw;
    // writes
    if(j===0) add('prefix(system+agent+task)', (cw)*P.write/1e6+ cr*P.read/1e6);
    else { add(keyOf(per[j-1].ks)+' (result re-write)', cw*P.write/1e6);
      // reads: prefix then deltas
      let left=cr; const pre=Math.min(left,P0); add('prefix(system+agent+task)',pre*P.read/1e6); left-=pre;
      for(let i=1;i<j&&left>0;i++){const t=Math.min(left,delta[i]); add(keyOf(per[i-1].ks)+' (result re-read)',t*P.read/1e6); left-=t;}
      if(left>0) add('unattributed-read',left*P.read/1e6);
    }
    add('OUTPUT:'+keyOf(per[j].ks), per[j].ch*tokPerChar*P.out/1e6);
  }
  return A;
}
EOF
