1	// $0 checks of the init --auto cases: each fixture materializes, its expected config passes the real scaffold, `config validate`
2	// and `config packs`, every planted convention quotes a real line, and the deterministic graders pass on a hand-built good
3	// run and fail on an empty or half-done one. No model runs here.
4	import assert from 'node:assert/strict';
5	import { execFileSync } from 'node:child_process';
6	import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
7	import { tmpdir } from 'node:os';
8	import path from 'node:path';
9	import { describe, it } from 'node:test';
10	import { parse } from 'yaml';
11	import { materialize } from '../../fixtures/materialize.mjs';
12	import { FIXTURES, fixtureByName } from '../../fixtures/definitions.mjs';
13	import { EVALS, render } from './cases.mjs';
14	import { INIT_TRUTHS, expectedConfig } from './init-cases.mjs';
15	
16	const ROOT = path.dirname(EVALS);
17	const CLI = path.join(ROOT, 'scripts', 'ambicode.mjs');
18	const SCAFFOLD = path.join(ROOT, 'skills', 'init', 'scripts', 'scaffold.mjs');
19	const FILES = render();
20	
21	/** What a model would write for each convention: a paraphrase, so the lenient patterns are tested on prose and not on the quote alone. */
22	const WORDING = {
23	  'tw-error-codes': 'Raise TidewatchError subclasses with a TW-nnn code as the first argument.',
24	  'test-names': 'Name tests test_<module>__<behaviour>, with a double underscore.',
25	  'keyword-only-args': 'Take every parameter after the first as a keyword-only argument.',
26	  'wrap-with-operation': 'Wrap each returned error with the package and function that returns it: pkg.Func: %w.',
27	  'injected-clock': 'Take a core.Clock instead of calling time.Now outside internal/clock.',
28	  'core-interfaces': 'Packages under internal/ share types and interfaces through internal/core.',
29	  'value-class-ids': 'Identifiers are value classes, never a bare String in a signature.',
30	  'outcome-not-exceptions': 'Return an expected failure as Outcome.Rejected instead of throwing.',
31	  'structured-log-keys': 'Log with structured key-values through addKeyValue.',
32	  'deci-celsius-names': 'Name every temperature with a _dc suffix: tenths of a degree Celsius.',
33	  'invariant-expect': 'Use expect with an invariant: message instead of unwrap.',
34	  'register-app-routes': 'Each routes module exports register(app) and the server calls it.',
35	};
36	
37	const frontmatter = (text) => parse(text.split('---')[1]);
38	const graderTexts = (name) => [...FILES].filter(([file]) => file.startsWith(`cases/${name}/graders/`)).map(([file, text]) => ({ name: path.basename(file, '.md'), ...frontmatter(text) }));
39	
40	/** The three deterministic grader types a case uses, evaluated the way the harness documents them; a missing file never matches. */
41	function passes(grader, workspace, trace) {
42	  if (grader.type === 'file_exists') return existsSync(path.join(workspace, grader.path));
43	  if (grader.type === 'regex') {
44	    const file = path.join(workspace, grader.target.path);
45	    if (!existsSync(file)) return false;
46	    const hit = new RegExp(grader.pattern).test(readFileSync(file, 'utf8'));
47	    return grader.match === 'not_contains' ? !hit : hit;
48	  }
49	  if (grader.type === 'tool_used') {
50	    const pattern = new RegExp(grader.input_match);
51	    const count = trace.filter((call) => call.name === grader.tool && pattern.test(JSON.stringify(call.input))).length;
52	    return count >= (grader.min ?? 1) && (grader.max === undefined || count <= grader.max);
53	  }
54	  throw new Error(`${grader.name}: ${grader.type} is not evaluated here`);
55	}
56	
57	const cli = (cwd, ...args) => execFileSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
58	
59	/** A run as init leaves it: scaffold, the expected config, copied packs, context stubs and one draft per planted convention. */
60	async function goodRun(truth, parent) {
61	  const repo = path.join(parent, 'repo');
62	  await materialize(fixtureByName(truth.fixture), repo);
63	  const trace = [{ name: 'Bash', input: { command: `node "/p/skills/init/scripts/scaffold.mjs" --task init` } }, { name: 'Agent', input: { subagent_type: 'ambicode:scout', prompt: 'Map this repo' } }];
64	  execFileSync(process.execPath, [SCAFFOLD, '--task', 'init'], { cwd: repo });
65	  writeFileSync(path.join(repo, '.ambicode', 'config.yaml'), expectedConfig(truth));
66	  assert.equal(cli(repo, 'config', 'validate').trim(), 'ok');
67	  cli(repo, 'config', 'packs', '--task', 'init');
68	  trace.push({ name: 'Bash', input: { command: 'node ambicode.mjs config packs --task init' } }, { name: 'Bash', input: { command: 'node ambicode.mjs config validate --task init' } });
69	  for (const name of ['overview', 'navigation', 'conventions', 'index']) writeFileSync(path.join(repo, '.ambicode', 'context', `${name}.md`), `# ${name}\n`);
70	  mkdirSync(path.join(repo, '.ambicode', 'policies', 'drafts'), { recursive: true });
71	  for (const convention of truth.conventions) {
72	    const file = path.join(repo, '.ambicode', 'policies', 'drafts', `${convention.id}.yaml`);
73	    const content = `schemaVersion: 1\nid: ${convention.id}\nrules:\n  - id: ${convention.id}\n    instruction: ${WORDING[convention.id]}\n    source: { quote: ${JSON.stringify(convention.quote)}, location: ${JSON.stringify(convention.location)} }\n`;
74	    writeFileSync(file, content);
75	    trace.push({ name: 'Write', input: { file_path: file, content } });
76	  }
77	  return { repo, trace };
78	}
79	
80	describe('init --auto cases', () => {
81	  it('five cases, each on a different fixture', () => {
82	    assert.deepEqual(INIT_TRUTHS.map((truth) => truth.slug), ['ts', 'python', 'go', 'jvm', 'monorepo']);
83	    assert.equal(new Set(INIT_TRUTHS.map((truth) => truth.fixture)).size, 5);
84	  });
85	
86	  for (const truth of INIT_TRUTHS) {
87	    const name = `init-auto-${truth.slug}`;
88	    const fixture = fixtureByName(truth.fixture);
89	    const written = Object.assign({}, ...fixture.steps.map((step) => step.write ?? {}));
90	
91	    if (truth.conventions.length > 0) {
92	      it(`${name}: the fixture is 10-30 files and every planted convention quotes a real line`, () => {
93	        assert.ok(Object.keys(written).length >= 10 && Object.keys(written).length <= 30, `${Object.keys(written).length} files`);
94	        assert.equal(truth.conventions.length, 3);
95	        assert.equal(truth.conventions.filter((convention) => convention.basis === 'inferred').length, 1);
96	        for (const convention of truth.conventions) {
97	          assert.ok(convention.quote.length >= 20, `${convention.id}: quote under 20 characters`);
98	          const [file, line] = convention.location.split(/:(?=\d+$)/);
99	          assert.ok(written[file] !== undefined, `${convention.id}: ${file} is not in the fixture`);
100	          assert.ok(written[file].split('\n')[Number(line) - 1].includes(convention.quote), `${convention.id}: line ${line} of ${file} lacks the quote`);
101	          if (convention.document !== undefined) {
102	            const [doc, docLine] = convention.document.split(/:(?=\d+$)/);
103	            assert.ok(written[doc].split('\n')[Number(docLine) - 1].length > 0, `${convention.id}: ${convention.document} is empty`);
104	          }
105	          // A written convention is in the contributor document; an inferred one must not be.
106	          const documented = /^CONTRIBUTING\.md:/.test(convention.location) || convention.document !== undefined;
107	          assert.equal(documented, convention.basis === 'written', `${convention.id}: basis ${convention.basis}`);
108	        }
109	      });
110	    }
111	
112	    it(`${name}: the expected config passes scaffold, config validate and config packs; graders pass on a good run and fail on bad ones`, async () => {
113	      const parent = mkdtempSync(path.join(tmpdir(), 'init-case-'));
114	      try {
115	        const { repo, trace } = await goodRun(truth, parent);
116	        const graders = graderTexts(name).filter((grader) => grader.type !== 'llm');
117	        assert.ok(graders.length >= 20, `${graders.length} deterministic graders`);
118	        assert.equal(graderTexts(name).filter((grader) => grader.type === 'llm').length, 1);
119	        const failing = graders.filter((grader) => !passes(grader, repo, trace)).map((grader) => grader.name);
120	        assert.deepEqual(failing, [], 'graders failing on the good run');
121	
122	        // Scaffold only: what a run that stops after step 1 leaves behind.
123	        const bare = path.join(parent, 'bare');
124	        await materialize(fixtureByName(truth.fixture), bare);
125	        execFileSync(process.execPath, [SCAFFOLD, '--task', 'init'], { cwd: bare });
126	        const scaffoldOnly = graders.filter((grader) => passes(grader, bare, [])).map((grader) => grader.name);
127	        const mustFail = graders.filter((grader) => !['never', 'no-misfit-pack', 'no-config-rules', 'gitignore-has-ambicode', 'config-written', 'schema-version', 'projects-single'].some((kept) => grader.name === kept || (kept === 'never' && grader.max === 0)));
128	        assert.deepEqual(mustFail.filter((grader) => scaffoldOnly.includes(grader.name)).map((grader) => grader.name), [], 'graders passing on a scaffold-only run');
129	
130	        // Empty directory and empty trace: only the "never" graders may pass.
131	        const empty = mkdtempSync(path.join(parent, 'empty-'));
132	        assert.deepEqual(graders.filter((grader) => passes(grader, empty, [])).map((grader) => grader.name).sort(), graders.filter((grader) => grader.max === 0).map((grader) => grader.name).sort());
133	
134	        // A misfit pack and an inline rules key each trip their grader.
135	        const config = path.join(repo, '.ambicode', 'config.yaml');
136	        const original = readFileSync(config, 'utf8');
137	        writeFileSync(config, `${original}    - builtin/angular-http\n`);
138	        assert.equal(passes(graders.find((grader) => grader.name === 'no-misfit-pack'), repo, trace), false);
139	        writeFileSync(config, `${original}rules:\n  - id: x\n    instruction: y\n`);
140	        assert.equal(passes(graders.find((grader) => grader.name === 'no-config-rules'), repo, trace), false);
141	        writeFileSync(config, original);
142	      } finally {
143	        rmSync(parent, { recursive: true, force: true });
144	      }
145	    });
146	  }
147	
148	  it('a draft that misses a planted convention fails only its grader', () => {
149	    const grader = graderTexts('init-auto-go').find((one) => one.name === 'draft-injected-clock');
150	    const draft = (text) => [{ name: 'Write', input: { file_path: '/r/.ambicode/policies/drafts/a.yaml', content: text } }];
151	    assert.equal(passes(grader, '/nowhere', draft('instruction: Take a core.Clock instead of calling time.Now')), true);
152	    assert.equal(passes(grader, '/nowhere', draft('instruction: Wrap errors with %w')), false);
153	    assert.equal(passes(grader, '/nowhere', [{ name: 'Write', input: { file_path: '/r/src/x.go', content: 'time.Now' } }]), false);
154	  });
155	
156	  it('the harness has Agent for the scout-invoked grader', () => {
157	    for (const truth of INIT_TRUTHS) assert.match(FILES.get(`cases/init-auto-${truth.slug}/prompt.md`), /allowed_tools: \[[^\]]*\bAgent\b/);
158	  });
159	
160	  it('every new fixture is an uninitialised repository with no install step', () => {
161	    for (const truth of INIT_TRUTHS.slice(1)) assert.equal(fixtureByName(truth.fixture).install, undefined);
162	    assert.equal(FIXTURES.filter((fixture) => /^(py-service|go-module|jvm-gradle|monorepo-rust)/.test(fixture.name)).length, 4);
163	  });
164	});
