// Seed stores the parcels in order and stops at the first failure.
func (s *Store) Seed(parcels ...core.Parcel) error {
    for _, parcel := range parcels {
        if err := s.Put(parcel); err != nil {
            return fmt.Errorf("memstore.Seed: %w", err)
        }
    }
    return nil
}
