// Open lists the four two-hour slots of a day, starting at 08:00.
func Open(day time.Time) []Slot {
    start := time.Date(day.Year(), day.Month(), day.Day(), 8, 0, 0, 0, day.Location())
    out := make([]Slot, 0, 4)
