/// Eases a ramp: slow start, slow finish. Fraction is in thousandths, 0..=1000.
pub fn ease_thousandths(fraction: u32) -> u32 {
    let f = i64::from(fraction.min(1000));
    ((3 * f * f * 1000 - 2 * f * f * f) / 1_000_000) as u32
}
