use std::fmt;

use crate::message::Message;

#[derive(Debug, PartialEq, Eq)]
pub struct ProtocolError(pub String);

impl fmt::Display for ProtocolError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "protocol: {}", self.0)
    }
}

impl std::error::Error for ProtocolError {}

pub fn encode(message: &Message) -> String {
    match message {
        Message::Start { firing_id } => format!("START {firing_id}"),
        Message::Stop { firing_id } => format!("STOP {firing_id}"),
        Message::Setpoint { firing_id, target_dc } => format!("SET {firing_id} {target_dc}"),
    }
}

pub fn decode(line: &str) -> Result<Message, ProtocolError> {
    let fields: Vec<&str> = line.split_whitespace().collect();
    let number = |text: &str| text.parse::<i64>().map_err(|_| ProtocolError(format!("bad number {text}")));
    match fields.as_slice() {
        ["START", id] => Ok(Message::Start { firing_id: number(id)? as u32 }),
        ["STOP", id] => Ok(Message::Stop { firing_id: number(id)? as u32 }),
        ["SET", id, target] => Ok(Message::Setpoint {
            firing_id: number(id)? as u32,
            target_dc: number(target)? as i32,
        }),
        _ => Err(ProtocolError(format!("unknown line {line}"))),
    }
}
