1	// $0 checks of the init --auto cases: each fixture materializes, its expected config passes the real scaffold, `config validate`
2	// and `config packs`, every planted convention quotes a real line, and the deterministic graders pass on a hand-built good
3	// run and fail on an empty or half-done one. No model runs here.
4	import assert from 'node:assert/strict';
5	import { execFileSync } from 'node:child_process';
6	import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
7	import { tmpdir } from 'node:os';
8	import path from 'node:path';
9	import { describe, it } from 'node:test';
10	import { parse } from 'yaml';
11	import { materialize } from '../../fixtures/materialize.mjs';
12	import { FIXTURES, fixtureByName } from '../../fixtures/definitions.mjs';
13	import { EVALS, render } from './cases.mjs';
14	import { INIT_TRUTHS, expectedConfig, modulesOf } from './init-cases.mjs';
15	
16	const ROOT = path.dirname(EVALS);
17	const CLI = path.join(ROOT, 'scripts', 'ambicode.mjs');
18	const SCAFFOLD = path.join(ROOT, 'skills', 'init', 'scripts', 'scaffold.mjs');
19	const FILES = render();
20	
21	/** What a model would write for each convention: a paraphrase, so the tight patterns are tested on prose and not on the quote alone. */
22	const WORDING = {
23	  'context-index-imports': 'Reach another context through its index.ts, never through its domain or application folders.',
24	  'event-names': 'Name events <context>.<past-tense-verb>, for example lending.loan-returned.',
25	  'use-case-factories': 'Write each use case as a factory: (deps: CatalogDeps) => async (input) => result.',
26	  'create-returns-result': 'Build entities with createX functions that return Result<Entity, DomainError>.',
27	  'tw-error-codes': 'Raise TidewatchError subclasses with a TW-nnn code as the first argument.',
28	  'test-names': 'Name tests test_<module>__<behaviour>, with a double underscore.',
29	  'keyword-only-args': 'Take every parameter after the first as a keyword-only argument.',
30	  'plugin-constant': 'Each adapter folder ends plugin.py with PLUGIN = SourcePlugin(name=..., parse=...).',
31	  'wrap-with-operation': 'Wrap each returned error with the package and function that returns it: pkg.Func: %w.',
32	  'injected-clock': 'Take a core.Clock instead of calling time.Now outside internal/clock.',
33	  'core-interfaces': 'Constructors take interfaces from internal/core, such as core.Store and core.Clock.',
34	  'interface-assertions': 'Assert that a type satisfies its interface with var _ core.Store = (*Store)(nil).',
35	  'value-class-ids': 'Identifiers are value classes, never a bare String in a signature.',
36	  'outcome-not-exceptions': 'Return an expected failure as Outcome.Rejected instead of throwing.',
37	  'structured-log-keys': 'Log with structured key-values through addKeyValue.',
38	  'use-case-invoke': 'Every use case is a class with a single operator fun invoke.',
39	  'deci-celsius-names': 'Name every temperature with a _dc suffix: tenths of a degree Celsius.',
40	  'invariant-expect': 'Use expect with an invariant: message instead of unwrap.',
41	  'register-app-routes': 'Each routes module exports register(app) and the server calls it.',
42	  'error-trait-impl': 'Every crate error type implements std::error::Error.',
43	};
44	
45	/** What a scout would say after reading only folder and file names: none of it may satisfy a convention's pattern. */
46	const NAME_GUESS = {
47	  'context-index-imports': 'Contexts are separate folders under src/contexts.',
48	  'event-names': 'There is a shared event bus in the shared kernel.',
49	  'use-case-factories': 'Use cases live in the application folder of each context.',
50	  'create-returns-result': 'Domain code returns a Result type.',
51	  'tw-error-codes': 'Errors live in domain/errors.py and are named after what went wrong.',
52	  'test-names': 'Tests sit in tests/ with one file per module.',
53	  'keyword-only-args': 'Handlers are in api/handlers, one file per endpoint.',
54	  'plugin-constant': 'Feed adapters are in plugins/sources, one folder per feed.',
55	  'wrap-with-operation': 'Errors are returned, not thrown.',
56	  'injected-clock': 'There is a clock package.',
57	  'core-interfaces': 'internal/core holds the shared types.',
58	  'interface-assertions': 'Each package has a constructor named New.',
59	  'value-class-ids': 'There are ids in the domain.',
60	  'outcome-not-exceptions': 'The domain has an Outcome type.',
61	  'structured-log-keys': 'Services write log lines.',
62	  'use-case-invoke': 'Use cases are in application/usecase.',
63	  'deci-celsius-names': 'Temperatures are integers.',
64	  'invariant-expect': 'Rust code checks its inputs.',
65	  'register-app-routes': 'Routes are in dashboard/src/routes.',
66	  'error-trait-impl': 'Each crate has an error module.',
67	};
68	
69	const frontmatter = (text) => parse(text.split('---')[1]);
70	const graderTexts = (name) => [...FILES].filter(([file]) => file.startsWith(`cases/${name}/graders/`)).map(([file, text]) => ({ name: path.basename(file, '.md'), ...frontmatter(text) }));
71	
72	/** The deterministic grader types a case uses, evaluated the way the harness documents them; a missing file never matches. */
73	function passes(grader, workspace, trace) {
74	  if (grader.type === 'file_exists') return existsSync(path.join(workspace, grader.path));
75	  if (grader.type === 'regex') {
76	    const file = path.join(workspace, grader.target.path);
77	    if (!existsSync(file)) return false;
78	    const text = readFileSync(file, 'utf8');
79	    if (grader.match?.startsWith('count:')) return (text.match(new RegExp(grader.pattern, 'g')) ?? []).length === Number(grader.match.slice(6));
80	    const hit = new RegExp(grader.pattern).test(text);
81	    return grader.match === 'not_contains' ? !hit : hit;
82	  }
83	  if (grader.type === 'tool_used') {
84	    const pattern = new RegExp(grader.input_match);
85	    const count = trace.filter((call) => call.name === grader.tool && pattern.test(JSON.stringify(call.input))).length;
86	    return count >= (grader.min ?? 1) && (grader.max === undefined || count <= grader.max);
87	  }
88	  throw new Error(`${grader.name}: ${grader.type} is not evaluated here`);
89	}
90	
91	const cli = (cwd, ...args) => execFileSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
92	
93	/** A run as init leaves it: scaffold, the expected config, copied packs, context stubs and one draft per planted convention. */
94	async function goodRun(truth, parent) {
95	  const repo = path.join(parent, 'repo');
96	  await materialize(fixtureByName(truth.fixture), repo);
97	  const trace = [{ name: 'Bash', input: { command: `node "/p/skills/init/scripts/scaffold.mjs" --task init` } }, { name: 'Agent', input: { subagent_type: 'ambicode:scout', prompt: 'Map this repo' } }];
98	  execFileSync(process.execPath, [SCAFFOLD, '--task', 'init'], { cwd: repo });
99	  writeFileSync(path.join(repo, '.ambicode', 'config.yaml'), expectedConfig(truth));
100	  assert.equal(cli(repo, 'config', 'validate').trim(), 'ok');
101	  cli(repo, 'config', 'packs', '--task', 'init');
102	  trace.push({ name: 'Bash', input: { command: 'node ambicode.mjs config packs --task init' } }, { name: 'Bash', input: { command: 'node ambicode.mjs config validate --task init' } });
103	  const context = path.join(repo, '.ambicode', 'context');
104	  const modules = modulesOf(truth);
105	  for (const name of ['overview', 'navigation', 'conventions']) writeFileSync(path.join(context, `${name}.md`), `# ${name}\n\n- Everything here is a description of the code as it is.\n`);
106	  for (const module of modules) {
107	    mkdirSync(path.dirname(path.join(context, module.note)), { recursive: true });
108	    writeFileSync(path.join(context, module.note), `# ${module.dir} module\n`);
109	  }
110	  writeFileSync(path.join(context, 'index.md'), `# Index\n${modules.map((module) => `${'  '.repeat(module.depth - 1)}- [${module.dir}](${module.note})\n`).join('')}`);
111	  trace.push({ name: 'Read', input: { file_path: path.join(repo, 'CONTRIBUTING.md') } });
112	  mkdirSync(path.join(repo, '.ambicode', 'policies', 'drafts'), { recursive: true });
113	  for (const convention of truth.conventions) {
114	    const file = path.join(repo, '.ambicode', 'policies', 'drafts', `${convention.id}.yaml`);
115	    const content = `schemaVersion: 1\nid: ${convention.id}\nrules:\n  - id: ${convention.id}\n    instruction: ${WORDING[convention.id]}\n    source: { quote: ${JSON.stringify(convention.quote)}, location: ${JSON.stringify(convention.location)} }\n`;
116	    writeFileSync(file, content);
117	    trace.push({ name: 'Write', input: { file_path: file, content } });
118	  }
119	  return { repo, trace };
120	}
121	
122	describe('init --auto cases', () => {
123	  it('five cases, each on a different fixture', () => {
124	    assert.deepEqual(INIT_TRUTHS.map((truth) => truth.slug), ['ts', 'python', 'go', 'jvm', 'monorepo']);
125	    assert.equal(new Set(INIT_TRUTHS.map((truth) => truth.fixture)).size, 5);
126	  });
127	
128	  for (const truth of INIT_TRUTHS) {
129	    const name = `init-auto-${truth.slug}`;
130	    const fixture = fixtureByName(truth.fixture);
131	    const written = Object.assign({}, ...fixture.steps.map((step) => step.write ?? {}));
132	
133	    it(`${name}: the fixture has 60-150 files, about 30 modules, and every planted convention quotes a real line`, () => {
134	      assert.ok(Object.keys(written).length >= 60 && Object.keys(written).length <= 150, `${Object.keys(written).length} files`);
135	      const modules = modulesOf(truth);
136	      assert.ok(modules.length >= 28 && modules.length <= 36, `${modules.length} modules`);
137	      assert.equal(truth.conventions.length, 4);
138	      assert.equal(truth.conventions.filter((convention) => convention.basis === 'inferred').length, 2);
139	      for (const convention of truth.conventions) {
140	        assert.ok(convention.quote.length >= 20, `${convention.id}: quote under 20 characters`);
141	        const [file, line] = convention.location.split(/:(?=\d+$)/);
142	        assert.ok(written[file] !== undefined, `${convention.id}: ${file} is not in the fixture`);
143	        assert.ok(written[file].split('\n')[Number(line) - 1].includes(convention.quote), `${convention.id}: line ${line} of ${file} lacks the quote`);
144	        if (convention.document !== undefined) {
145	          const [doc, docLine] = convention.document.split(/:(?=\d+$)/);
146	          assert.ok(written[doc].split('\n')[Number(docLine) - 1].length > 0, `${convention.id}: ${convention.document} is empty`);
147	        }
148	        // A written convention is in the contributor document; an inferred one must not be.
149	        const documented = /^CONTRIBUTING\.md:/.test(convention.location) || convention.document !== undefined;
150	        assert.equal(documented, convention.basis === 'written', `${convention.id}: basis ${convention.basis}`);
151	      }
152	    });
153	
154	    it(`${name}: the expected config passes scaffold, config validate and config packs; graders pass on a good run and fail on bad ones`, async () => {
155	      const parent = mkdtempSync(path.join(tmpdir(), 'init-case-'));
156	      try {
157	        const { repo, trace } = await goodRun(truth, parent);
158	        const graders = graderTexts(name).filter((grader) => grader.type !== 'llm');
159	        assert.ok(graders.length >= 30, `${graders.length} deterministic graders`);
160	        assert.equal(graderTexts(name).filter((grader) => grader.type === 'llm').length, 1);
161	        // The expected module notes are what the real `context tree` prints on the scaffolded fixture.
162	        const roots = [...new Set(truth.projects.flatMap((project) => project.paths.map((p) => `${project.root === '.' ? '' : `${project.root}/`}${p}`.replace(/\/$/, ''))))];
163	        const printed = cli(repo, 'context', 'tree', ...roots.flatMap((root) => ['--root', root])).split('\n').filter((line) => line.startsWith('modules/')).map((line) => line.split(/\s+/)[0]);
164	        assert.deepEqual(modulesOf(truth).map((module) => module.note), printed, 'module notes match context tree');
165	        const failing = graders.filter((grader) => !passes(grader, repo, trace)).map((grader) => grader.name);
166	        assert.deepEqual(failing, [], 'graders failing on the good run');
167	
168	        // Scaffold only: what a run that stops after step 1 leaves behind.
169	        const bare = path.join(parent, 'bare');
170	        await materialize(fixtureByName(truth.fixture), bare);
171	        execFileSync(process.execPath, [SCAFFOLD, '--task', 'init'], { cwd: bare });
172	        const scaffoldOnly = graders.filter((grader) => passes(grader, bare, [])).map((grader) => grader.name);
173	        const mustFail = graders.filter((grader) => !['never', 'no-misfit-pack', 'no-config-rules', 'gitignore-has-ambicode', 'config-written', 'schema-version', 'projects-single'].some((kept) => grader.name === kept || (kept === 'never' && grader.max === 0)));
174	        assert.deepEqual(mustFail.filter((grader) => scaffoldOnly.includes(grader.name)).map((grader) => grader.name), [], 'graders passing on a scaffold-only run');
175	
176	        // Empty directory and empty trace: only the "never" graders may pass.
177	        const empty = mkdtempSync(path.join(parent, 'empty-'));
178	        assert.deepEqual(graders.filter((grader) => passes(grader, empty, [])).map((grader) => grader.name).sort(), graders.filter((grader) => grader.max === 0).map((grader) => grader.name).sort());
179	
180	        // A misfit pack and an inline rules key each trip their grader.
181	        const config = path.join(repo, '.ambicode', 'config.yaml');
182	        const original = readFileSync(config, 'utf8');
183	        writeFileSync(config, `${original}    - builtin/angular-http\n`);
184	        assert.equal(passes(graders.find((grader) => grader.name === 'no-misfit-pack'), repo, trace), false);
185	        writeFileSync(config, `${original}rules:\n  - id: x\n    instruction: y\n`);
186	        assert.equal(passes(graders.find((grader) => grader.name === 'no-config-rules'), repo, trace), false);
187	        writeFileSync(config, original);
188	
189	        // Scout output that is wrong in one place trips only the grader for that place.
190	        const context = path.join(repo, '.ambicode', 'context');
191	        const indexFile = path.join(context, 'index.md');
192	        const index = readFileSync(indexFile, 'utf8');
193	        const modules = modulesOf(truth);
194	        writeFileSync(indexFile, index.split('\n').filter((line) => !line.includes(`(${modules[2].note})`)).join('\n'));
195	        const afterDrop = graders.filter((grader) => !passes(grader, repo, trace)).map((grader) => grader.name);
196	        assert.deepEqual(afterDrop.filter((grader) => grader.startsWith('modules-linked-')), [`modules-linked-1-of-${Math.ceil(modules.length / 6)}`], 'only the coverage group that names the dropped module fails');
197	        assert.ok(afterDrop.includes('index-links-every-module') && afterDrop.includes('index-has-no-extra-notes'), 'the whole-tree grader and the count both see a missing module');
198	        writeFileSync(indexFile, `${index}- [invented](modules/invented.md)\n`);
199	        assert.equal(passes(graders.find((grader) => grader.name === 'index-has-no-extra-notes'), repo, trace), false);
200	        assert.equal(passes(graders.find((grader) => grader.name === 'index-links-every-module'), repo, trace), true);
201	        writeFileSync(indexFile, index);
202	        const conventions = path.join(context, 'conventions.md');
203	        writeFileSync(conventions, '# conventions\n\n- Every handler must return a reply.\n');
204	        assert.equal(passes(graders.find((grader) => grader.name === 'conventions-descriptive'), repo, trace), false);
205	        assert.equal(passes(graders.find((grader) => grader.name === 'contributor-doc-read'), repo, trace.filter((call) => call.name !== 'Read')), false);
206	
207	        // Each planted convention's draft grader accepts a paraphrase of the rule and refuses what folder names alone give.
208	        for (const convention of truth.conventions) {
209	          const grader = graders.find((one) => one.name === `draft-${convention.id}`);
210	          const draft = (text) => [{ name: 'Write', input: { file_path: '/r/.ambicode/policies/drafts/a.yaml', content: `instruction: ${text}` } }];
211	          assert.equal(passes(grader, '/nowhere', draft(WORDING[convention.id])), true, `${convention.id}: paraphrase`);
212	          assert.equal(passes(grader, '/nowhere', draft(NAME_GUESS[convention.id])), false, `${convention.id}: name-only guess`);
213	        }
214	      } finally {
215	        rmSync(parent, { recursive: true, force: true });
216	      }
217	    });
218	  }
219	
220	  it('a draft that misses a planted convention fails only its grader', () => {
221	    const grader = graderTexts('init-auto-go').find((one) => one.name === 'draft-injected-clock');
222	    const draft = (text) => [{ name: 'Write', input: { file_path: '/r/.ambicode/policies/drafts/a.yaml', content: text } }];
