    assert.deepEqual(out.check.problems, []);
    const app = await noteText(root, 'modules/src/app.md');
    assert.ok(tokensOf(app) <= 38);
    assert.match(app, /alphaOne/);
    assert.doesNotMatch(app, /BetaClass/);

