    maxContextBytes: null
    excludePaths: []
  task: { model: sonnet, effort: medium, timeoutMinutes: 60, checkTimeoutSeconds: 120 }
  plan: { model: sonnet, effort: medium, timeoutMinutes: 30 }
  investigate: { model: sonnet, effort: low, timeoutMinutes: 15 }
  rules: { model: sonnet, effort: medium, timeoutMinutes: 15 }
requirements:
  runtimes: {}                   # node: ">=20"
  mcps: []                       # MCP server names; the first Jira/Confluence one is the requirements server
  lsps: []
  env: []                        # names only
# One entry per project (a monorepo lists each package). A filled entry:
#   - id: web                    # kebab-case
#     root: .                    # where commands run
#     paths: [src/]              # working code roots
#     ecosystem: { languages: [typescript], frameworks: [react], packageManager: pnpm }
#     include: ["src/**"]        # globs agents may read and edit
#     exclude: ["**/*.test.*"]   # globs agents ignore
#     ignored: [node_modules/]   # git-ignored, hidden from Glob results; init fills it
#     packs: []                  # builtin/<id> from `config packs --list`; `config packs` copies each into policyFiles
#     policyFiles: [.ambicode/policies/angular/angular-http.yaml]   # editable copies (replaces: builtin/<id>) and packs from /ambicode:rules
#     commands: { dev: "pnpm dev" }
#     checks:                    # {file} is replaced for single-file runs
#       test: { all: "pnpm vitest run", file: "pnpm vitest run {file}" }
projects:
  - id: __PROJECT_ID__
    root: .
    paths: []
    ecosystem: { languages: [], frameworks: [], packageManager: null }
    include: []
    exclude: []
    ignored: []                  # git-ignored, hidden from Glob results; init fills it
    packs: []
    policyFiles: []
    commands: {}
    checks: {}
