R='/Users/KillBill/Documents/projects/mine/ai/ambicode/evals/cases/results/'
arms={'fixed':['06-11-20','00-28-28','06-15-19','00-32-08'],'presc':['06-37-16'],'comp':['06-46-23','06-48-53']}
def walk(p):
