for arm,ss in arms.items():
  for s in ss:
    t=glob.glob(R+'traces/plugin/2026-10-21T'+s+'*')[0]
    agg=json.load(open(glob.glob(R+'2026-10-21T'+s+'*/aggregate-result.json')[0]))
    case=agg['cases'][0]; runs=case['arms']['with']
    for i,run in enumerate(runs,1):
        name=f"{case['name']}-{i}"
        ctx=f"{t}/{name}.ambicode/.ambicode/context"
        g={x['name']:x['passed'] for x in run['graders']}
        grp=lambda pre:(sum(v for k,v in g.items() if k.startswith(pre)),sum(1 for k in g if k.startswith(pre)))
