        print(' graders:',{p:grp(p) for p in sel}, 'fails:',[k for k,v in g.items() if not v])
        # scout trace
        sc_turns=0;tools=[];prompt=None
        for l in open(f"{t}/{name}.jsonl"):
            d=json.loads(l)
            if d['type']=='assistant':
                for b in d['message']['content']:
                    if b['type']=='tool_use':
                        if b['name'] in('Agent','Task') and not d.get('parent_tool_use_id'): prompt=b['input'].get('prompt')
