        print(' bash:',[x[1][:110] for x in tools if x[0]=='Bash'])
        print(' prompt:',(prompt or 'NONE')[:600])
        if not os.path.isdir(ctx): print(' NO CONTEXT'); continue
        notes=[f for f in walk(ctx) if '/modules/' in f]
        idx=open(ctx+'/index.md').read() if os.path.exists(ctx+'/index.md') else ''
        dep=gt=0;
        for f in notes:
            txt=open(f).read()
            m=re.search(r'## Depends on\s*\n(.*?)(\n## |\Z)',txt,re.S)
            if m and re.search(r'\w',m.group(1)) and not re.fullmatch(r'\s*(-?\s*(none|n/a)\.?)\s*',m.group(1),re.I): dep+=1
            m=re.search(r'## Gotchas\s*\n(.*?)(\n## |\Z)',txt,re.S)
            if m and re.search(r'\w',m.group(1)) and not re.fullmatch(r'\s*(-?\s*(none|n/a)\.?)\s*',m.group(1),re.I): gt+=1
        truth=json.load(open(R+'../'+case['name']+'/truth.json')) if os.path.exists(R+'../'+case['name']+'/truth.json') else {}
        print(' notes',len(notes),'dep',dep,'gotchas',gt,'index chars',len(idx),'tok~',len(idx)//4)
        for n in ['overview','navigation','conventions']:
            p=f'{ctx}/{n}.md'; print(' ',n,len(open(p).read()) if os.path.exists(p) else None)
        cv=open(ctx+'/conventions.md').read() if os.path.exists(ctx+'/conventions.md') else ''
        ents=[x for x in re.split(r'\n(?=#{2,3} |- |\d+\. )',cv)]
        print(' conv headings',len(re.findall(r'^#{2,3} ',cv,re.M)),'bullets',len(re.findall(r'^[-*] ',cv,re.M)),'backticks',cv.count('`'),'paths',len(re.findall(r'[\w/]+\.\w{1,4}(:\d+)?',cv)))
